import logging
import re
import six
from .iperf_config import IperfDataTransferConfig
from .iperf_executor import SshExecutor

IPERF_CONFIG_CLIENT = {
    "buffer": "-w",
    "packet_size": "-l"
}

IPERF_CONFIG_SERVER = {
    "buffer": "-w"
}


class IperfCommand(object):
    _CHECK_CYGWIN_PROCESS = 'TASKLIST  /FI "IMAGENAME eq cygrunsrv.exe"'
    _IS_CYGWIN = 'Image Name'
    _NOT_CYGWIN = 'bash: TASKLIST: command not found'
    _QUERY_IPERF_IN_CYGWIN = 'netstat -ano | grep :{}'
    _QUERY_IPERF_IN_LINUX = 'netstat -anop | grep :{}'
    _KILL_PID_IN_CYGWIN = 'TASKKILL /F /PID {}'
    _KILL_PID_IN_LINUX = 'kill -9 {}'
    _KILL_PROCESS_TEMPLATE = """ps axf | grep iperf | grep {port} | grep -v grep | awk '{{print "kill -9 " $1}}' | sh"""

    _WIN_PING_CMD = 'ping {} -n 5'
    _WIN_PING_PATTERN = 'Lost = 0'
    _LINUX_PING_CMD = 'ping {} -c 5'
    _LINUX_PING_PATTERN = ' 0% packet loss'

    def __init__(self, dt_definition, configuration):
        self._config = IperfDataTransferConfig(dt_definition, configuration)

        self._app_server_config = self._config.get_app_server_config()
        self._ue_host_config = self._config.get_ue_host_config()
        self._app_server_ssh = SshExecutor(self._app_server_config)
        self._ue_host_ssh = SshExecutor(self._ue_host_config)

    def teardown(self):
        self._app_server_ssh.disconnect()
        self._ue_host_ssh.disconnect()

    def _create_iperf_server_cmd(self, port):
        """
        Create iperf command to run on iperf server side
        :param port:
        :return:
        """
        result = '{iperf} -s {udp_option} -p {port} -i {interval} {special_options} 2>&1'.format(
            iperf=self._get_iperf_server_filename(),
            udp_option=self._udp_option(),
            port=str(port),
            interval=self._config.get_iperf_interval(),
            special_options=self._special_server_run_options())

        logging.debug("Iperf server CMD: " + result)
        return result

    def _create_iperf_client_cmd(self, server_ip, port):
        """
        Create iperf command to run on iperf client side
        :param port:
        :return:
        """
        result = '{iperf} -c {server_ip} {udp} {band} -p {port} -t {duration} -i {interval} {special_options}' \
            ' 2>&1'.format(
                iperf=self._get_iperf_client_filename(),
                server_ip=server_ip,
                udp=self._udp_option(),
                band=self._udp_bandwidth_option(),
                interval=self._config.get_iperf_interval(),
                port=str(port),
                duration=str(self._config.get_duration()),
                special_options=self._special_client_run_options())
        logging.debug("iperf client CMD: {} ".format(result))
        return result

    def _kill_started_process(self):
        raise NotImplementedError

    def _is_cygwin_server(self, executor):
        executor.send_command(command=self._CHECK_CYGWIN_PROCESS)
        response = executor.read_output()
        if self._IS_CYGWIN in response:
            return True
        elif self._NOT_CYGWIN in response:
            return False
        else:
            raise RuntimeError('unexpected response from ssh session: {}'.format(response))

    def _check_if_ping_pass(self, ping_output):
        logging.info("Ping command output: {}".format(ping_output))
        if self._WIN_PING_PATTERN in re.findall(self._WIN_PING_PATTERN, ping_output):
            logging.info('IP Passthrough start and Delay scenarios run normally.')
        elif self._LINUX_PING_PATTERN in re.findall(self._LINUX_PING_PATTERN, ping_output):
            logging.info('IP Passthrough start and Delay scenarios run normally.')
        else:
            raise Exception('IP Passthrough start and Delay scenarios run abnormally.')

    def _udp_bandwidth_option(self):
        return '-b {}'.format(self._config.get_bandwidth())

    @staticmethod
    def _udp_option():
        return '-u'

    def _get_server_ip(self):
        """
        Get server IP address.

        :return: ip of iperf's server
        """
        raise NotImplementedError

    def _get_iperf_server_filename(self):
        """
        Get iperf server file name.

        :return: filename of iperf to run in server's cmd.
        """
        raise NotImplementedError

    def _get_iperf_client_filename(self):
        """
        Get iperf client file name.

        :return: filename of iperf to run in client's cmd.
        """
        raise NotImplementedError

    def _special_server_run_options(self):
        """
        Options to be added to cmd
        :return:
        """
        options = []
        # uplink: epc = server, downlink: prisma_app_server = server
        result = self._special_server_run_options_iperf_options(options)

        return ' '.join(result)

    def _special_client_run_options(self):
        """
        Options to be added to cmd
        """
        raise NotImplementedError

    def _special_client_run_options_iperf_options(self, options):

        suffix = "_client"
        configs_dict = IPERF_CONFIG_CLIENT
        if self._config.get_iperf_options() is None:
            return options
        if len(self._config.get_iperf_options()) == 0:
            return options
        for option_name, option_value in self._config.get_iperf_options().items():
            option_name = self._string_without_suffix(option_name, suffix)
            if option_name in configs_dict and option_value:
                options.append('{} {}'.format(configs_dict[option_name], option_value))
        return options

    def _special_server_run_options_iperf_options(self, options):
        suffix = "_server"
        configs_dict = IPERF_CONFIG_SERVER
        if self._config.get_iperf_options() is None:
            return options
        if len(self._config.get_iperf_options()) == 0:
            return options
        for option_name, option_value in self._config.get_iperf_options().items():
            option_name = self._string_without_suffix(option_name, suffix)
            if option_name in configs_dict and option_value:
                options.append('{} {}'.format(configs_dict[option_name], option_value))
        return options

    @staticmethod
    def _string_without_suffix(original_str, suffix):
        if original_str.endswith(suffix):
            return original_str[:-len(suffix)]
        return original_str

    def kill_remote_process_listening_port(self, port, executor):
        succeed = False
        try:
            for pid in self._list_pid_listening_port(port, executor):
                succeed = self._handle_killing_pid(pid, executor, succeed)
        except RuntimeError as e:
            logging.warning(e)
        return succeed

    def _handle_killing_pid(self, pid, executor, succeed):
        if self._is_cygwin_server(executor):
            cmd = self._KILL_PID_IN_CYGWIN.format(pid)
        else:
            cmd = self._KILL_PID_IN_LINUX.format(pid)
        stdout = executor.execute(command=cmd)
        if ('SUCCESS' in stdout) or (not stdout):
            succeed = True
        return succeed

    def _list_pid_listening_port(self, port, executor):
        stdout = self.__execute_query_iperf(port, executor)
        marker = ":{}".format(port)
        for line in stdout.split("\n"):
            # print("ssh from " + str(ue_pc_ip) + " got netstat line: " + str(line))
            if marker in line:
                pids = self._extract_pid_from_netstat_output(line)
                if pids:
                    success, to_yield = self._list_pid_listening_port_get_pid(pids, line, marker)
                    if success:
                        yield to_yield

    def __execute_query_iperf(self, port, executor):
        port = self._port_strip(port)
        if self._is_cygwin_server(executor):
            cmd = self._QUERY_IPERF_IN_CYGWIN.format(port)
        else:
            cmd = self._QUERY_IPERF_IN_LINUX.format(port)
        stdout = executor.execute(command=cmd)
        if not stdout:
            logging.debug("Can't found process, retry to confirm")
            stdout = executor.execute(command=cmd)
        return stdout

    @staticmethod
    def _port_strip(port):
        if isinstance(port, six.string_types):
            port = int(port.strip())
        return port

    @staticmethod
    def _extract_pid_from_netstat_output(line):
        regex = r"\s+([1-9]\d*)[^.,0-9]"
        pids = re.findall(regex, line)
        if pids:
            return pids
        regex2 = r"LISTENING\s+(\d+)$"
        return re.findall(regex2, line)

    @staticmethod
    def _list_pid_listening_port_get_pid(pids, line, marker):
        if len(pids) > 1:
            if 'CLOSE_WAIT' in line:
                return False, None
            raise Exception(
                "TO MANY PIDS FOR ONE LINE, line = '{}', pids = {}, marker = '{}'".format(line, pids, marker))
        return True, int(pids[0])


class IperfUpLinkCommand(IperfCommand):
    def __init__(self, dt_definition, configuration):
        super(IperfUpLinkCommand, self).__init__(dt_definition, configuration)
        self.iperf_port = self._app_server_config['iperf_port']

    def start_iperf_cmd(self):
        self._run_iperf_server_cmd()
        self._run_iperf_client_cmd()

    def _run_iperf_server_cmd(self):
        iperf_server_cmd = self._create_iperf_server_cmd(self.iperf_port)
        # To keep the iperf command alive before killed. Set pty False.
        self._app_server_ssh.send_command(iperf_server_cmd, get_pty=False)

    def _run_iperf_client_cmd(self):
        server_ips = self._get_server_ip()
        for server_ip in server_ips:
            iperf_client_cmd = self._create_iperf_client_cmd(server_ip=server_ip,
                                                             port=self.iperf_port)
            # To keep the iperf command alive before killed. Set pty False.
            self._ue_host_ssh.send_command(iperf_client_cmd, get_pty=False)

    def _kill_started_process(self):
        kill_cmd = self._KILL_PROCESS_TEMPLATE.format(port=self.iperf_port)
        logging.info("Kill process: {}".format(kill_cmd))
        self._app_server_ssh.execute(kill_cmd)

    def stop_iperf_cmd(self):
        logging.debug("Try to kill iperf on ue pc.")
        self.kill_remote_process_listening_port(self.iperf_port, self._ue_host_ssh)
        logging.debug("Try to kill iperf on app server.")
        self.kill_remote_process_listening_port(self.iperf_port, self._app_server_ssh)
        self._kill_started_process()

    def check_ip_pass_through(self):
        ping_cmd = self._LINUX_PING_CMD.format(self._app_server_config['iperf_interface_ip'])
        ping_cmd_result = self._ue_host_ssh.execute(ping_cmd, timeout=60)
        if "option -c." in ping_cmd_result:
            logging.info("It's WINDOWS, change the command.")
            ping_cmd = self._WIN_PING_CMD.format(self._app_server_config['iperf_interface_ip'])
            ping_cmd_result = self._ue_host_ssh.execute(ping_cmd, timeout=60)
        self._check_if_ping_pass(ping_cmd_result)

    def _get_server_ip(self):
        """
        Get server IP address.

        :return: ip of iperf's server
        """
        server_ips = self._app_server_config['iperf_interface_ip']
        if type(server_ips) is not list:
            server_ips = [server_ips]
        return server_ips

    def _get_iperf_server_filename(self):
        """
        Get iperf server file name.

        :return: filename of iperf to run in server's cmd.
        """
        # uplink: epc = server
        return self._app_server_config['iperf_path']

    def _get_iperf_client_filename(self):
        """
        Get iperf client file name.

        :return: filename of iperf to run in client's cmd.
        """
        # uplink: UE = client
        return self._ue_host_config['iperf_path']

    def _special_client_run_options(self):
        """
        Options to be added to cmd
        :return:
        """
        interface_ip = self._ue_host_config['iperf_interface_ip']
        if not interface_ip:
            return ""

        options = []
        option_b = '-B {}'.format(interface_ip)
        options.append(option_b)

        result = self._special_client_run_options_iperf_options(options)
        return ' '.join(result)


class IperfDownLinkCommand(IperfCommand):
    def __init__(self, dt_definition, configuration):
        super(IperfDownLinkCommand, self).__init__(dt_definition, configuration)
        self.iperf_port = self._ue_host_config['iperf_port']

    def start_iperf_cmd(self):
        self._run_iperf_server_cmd()
        self._run_iperf_client_cmd()

    def _run_iperf_server_cmd(self):
        iperf_server_cmd = self._create_iperf_server_cmd(self.iperf_port)
        # To keep the iperf command alive before killed. Set pty False.
        self._ue_host_ssh.send_command(iperf_server_cmd, get_pty=False)

    def _run_iperf_client_cmd(self):
        for ip in self._get_server_ip():
            iperf_client_cmd = self._create_iperf_client_cmd(server_ip=ip,
                                                             port=self.iperf_port)
            # To keep the iperf command alive before killed. Set pty False.
            self._app_server_ssh.send_command(iperf_client_cmd, get_pty=False)

    def stop_iperf_cmd(self):
        self.kill_remote_process_listening_port(self.iperf_port, self._ue_host_ssh)
        self.kill_remote_process_listening_port(self.iperf_port, self._app_server_ssh)
        self._kill_started_process()

    def _kill_started_process(self):
        kill_cmd = self._KILL_PROCESS_TEMPLATE.format(port=self.iperf_port)
        logging.info("Kill process: {}".format(kill_cmd))
        self._app_server_ssh.execute(kill_cmd)

    def check_ip_pass_through(self):
        server_ips = self._get_server_ip()
        for server_ip in server_ips:
            ping_cmd = self._LINUX_PING_CMD.format(server_ip)
            ping_cmd_result = self._app_server_ssh.execute(ping_cmd, timeout=60)
            if "option -c." in ping_cmd_result:
                logging.info("It's WINDOWS, change the command.")
                ping_cmd = self._WIN_PING_CMD.format(server_ip)
                ping_cmd_result = self._app_server_ssh.execute(ping_cmd, timeout=60)
            self._check_if_ping_pass(ping_cmd_result)

    def _get_server_ip(self):
        """
        Get server IP address.

        :return: ip of iperf's server
        """
        return self._config.get_ue_ip()

    def _get_iperf_server_filename(self):
        """
        Get iperf server file name.

        :return: filename of iperf to run in server's cmd.
        """
        # downlink: UE = server
        return self._ue_host_config['iperf_path']

    def _get_iperf_client_filename(self):
        """
        Get iperf client file name.

        :return: filename of iperf to run in client's cmd.
        """
        # downlink: epc = client
        return self._app_server_config['iperf_path']

    def _special_client_run_options(self):
        """
        Options to be added to cmd
        :return:
        """
        options = []
        option_b = '-B {}'.format(self._app_server_config['iperf_interface_ip'])
        options.append(option_b)

        result = self._special_client_run_options_iperf_options(options)
        return ' '.join(result)
